const defaultCount = defaultImages.length;
const defGoodRatio = 90; // good ratio of fetched data
const defGoodCount = Math.round(defaultCount * defGoodRatio / 100);
const defFairRatio = 65; // fair ratio of fetched data
const defFairCount = Math.round(defaultCount * defFairRatio / 100);

// Get a navigation page size per album size
const defaultPageSize = () => {
  const count = defaultImages.length;
  return count < 10 ? Math.round(count / 2)
    : (count < 100 ? 5 : 10);
};

// Build up a reverse lookup from filename to index
const dataFilesToIndex = (aList) => {
  return Object.fromEntries(aList.map(
    (value, index) => [value, index]));
};

// Hold a set of lookup tables
const dataLookup = {
  // filename to index of defaultImages
  files: dataFilesToIndex(defaultImages),
  // filename map lookup to mulu object
  names: {},
  // query key map to mulu object
  query: {}
};

// Get poem keys for query lookup
const getPoemKeys = (muluId, pageId) => {
  const array1 = [];
  const array2 = [];
  const array3 = [];
  const match1 = muluId ? muluId.match(regexName) : null;
  const match2 = pageId ? pageId.match(regexName) : null;
  const match3 = muluId ? muluId.match(regexMulu) : null;
  if (match1) {
    const [mid, yr, name] = match1;
    array1.push(...[mid, `${yr}-${name}`, `${name}-${yr}`]);
  }
  if (match2) {
    const [pid, yr, name] = match2;
    array2.push(...[pid, `${yr}-${name}`, `${name}-${yr}`]);
  }
  if (match3) {
    array3.push(match3[1]);
  }
  return [...new Set([...array1, ...array2, ...array3])];
}

